<?php
declare(strict_types=1);
$isHttps=isset($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!==''&&$_SERVER['HTTPS']!=='off';ini_set('session.use_strict_mode','1');session_name('coaching_tool_session');session_set_cookie_params(['httponly'=>true,'secure'=>$isHttps,'samesite'=>'Strict','path'=>'/']);session_start();header('Cache-Control: no-store, private');require_once dirname(__DIR__).'/app/bootstrap.php';
function formatH(string|int|null $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
$user=$_SESSION['user']??null;if(!is_array($user)||($user['role']??'')!=='coach'){http_response_code(403);exit('Die Formatebibliothek ist Coaches vorbehalten.');}
$db=coachingDatabase();$coach=(int)$user['id'];$token=$_SESSION['csrf_token']??'';if(!is_string($token)||strlen($token)!==64){$token=bin2hex(random_bytes(32));$_SESSION['csrf_token']=$token;}
$visibility=['privat'=>'Nur für mich','ausgewaehlte_coaches'=>'Ausgewählte Coaches','alle_coaches'=>'Alle Coaches'];$error='';$notice=isset($_GET['saved'])?'Format gespeichert.':'';
$values=['id'=>0,'titel'=>'','kategorie'=>'','kurzbeschreibung'=>'','ziel'=>'','ablauf'=>'','dauer_minuten'=>'','materialien'=>'','hinweise'=>'','quellen'=>'','tags'=>'','freigabe'=>'privat'];$selected=[];
$q=$db->query("SELECT id,vorname,nachname FROM benutzer WHERE aktiv=1 AND rolle='coach' ORDER BY nachname,vorname");$coaches=$q->fetchAll(PDO::FETCH_ASSOC);
if(isset($_GET['edit'])){$edit=filter_var($_GET['edit'],FILTER_VALIDATE_INT);if($edit!==false&&$edit>0){$q=$db->prepare('SELECT * FROM coaching_formate WHERE id=:id AND coach_benutzer_id=:owner');$q->execute(['id'=>$edit,'owner'=>$coach]);$row=$q->fetch(PDO::FETCH_ASSOC);if($row){$values=$row;$values['id']=(int)$row['id'];$q=$db->prepare('SELECT coach_benutzer_id FROM coaching_format_freigaben WHERE format_id=:id');$q->execute(['id'=>$edit]);$selected=array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN));}}}
if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($token,(string)($_POST['csrf_token']??''))){http_response_code(400);exit('Ungültige Anfrage.');}
$id=(int)($_POST['id']??0);$input=[];foreach(['titel','kategorie','kurzbeschreibung','ziel','ablauf','materialien','hinweise','quellen','tags'] as $key)$input[$key]=trim((string)($_POST[$key]??''));$input['freigabe']=(string)($_POST['freigabe']??'privat');$input['dauer_minuten']=(string)($_POST['dauer_minuten']??'');
$shareRaw=$_POST['freigabe_an']??[];$shareIds=is_array($shareRaw)?array_values(array_unique(array_filter(array_map('intval',$shareRaw),static fn(int $v):bool=>$v>0))):[];$selected=$shareIds;
if($input['titel']===''||strlen($input['titel'])>190||strlen($input['kategorie'])>100||strlen($input['kurzbeschreibung'])>1000||strlen($input['tags'])>500||!array_key_exists($input['freigabe'],$visibility))$error='Bitte fülle mindestens den Titel aus und prüfe die Feldlängen.';
elseif($input['ablauf']==='')$error='Bitte beschreibe den Ablauf des Formats.';
elseif($input['dauer_minuten']!==''&&((int)$input['dauer_minuten']<1||(int)$input['dauer_minuten']>600))$error='Die Dauer muss zwischen 1 und 600 Minuten liegen.';
elseif($input['freigabe']==='ausgewaehlte_coaches'&&$shareIds===[])$error='Wähle mindestens einen Coach für die Freigabe aus.';
else{try{$db->beginTransaction();$dur=$input['dauer_minuten']===''?null:(int)$input['dauer_minuten'];
if($id>0){$s=$db->prepare('UPDATE coaching_formate SET titel=:titel,kategorie=:kategorie,kurzbeschreibung=:kurz,ziel=:ziel,ablauf=:ablauf,dauer_minuten=:dauer,materialien=:materialien,hinweise=:hinweise,quellen=:quellen,tags=:tags,freigabe=:freigabe WHERE id=:id AND coach_benutzer_id=:owner');$s->execute(['titel'=>$input['titel'],'kategorie'=>$input['kategorie'],'kurz'=>$input['kurzbeschreibung'],'ziel'=>$input['ziel']?:null,'ablauf'=>$input['ablauf'],'dauer'=>$dur,'materialien'=>$input['materialien']?:null,'hinweise'=>$input['hinweise']?:null,'quellen'=>$input['quellen']?:null,'tags'=>$input['tags'],'freigabe'=>$input['freigabe'],'id'=>$id,'owner'=>$coach]);if($s->rowCount()===0){$check=$db->prepare('SELECT id FROM coaching_formate WHERE id=:id AND coach_benutzer_id=:owner');$check->execute(['id'=>$id,'owner'=>$coach]);if(!$check->fetchColumn())throw new RuntimeException('Format nicht gefunden.');}}
else{$s=$db->prepare('INSERT INTO coaching_formate (coach_benutzer_id,titel,kategorie,kurzbeschreibung,ziel,ablauf,dauer_minuten,materialien,hinweise,quellen,tags,freigabe) VALUES (:owner,:titel,:kategorie,:kurz,:ziel,:ablauf,:dauer,:materialien,:hinweise,:quellen,:tags,:freigabe)');$s->execute(['owner'=>$coach,'titel'=>$input['titel'],'kategorie'=>$input['kategorie'],'kurz'=>$input['kurzbeschreibung'],'ziel'=>$input['ziel']?:null,'ablauf'=>$input['ablauf'],'dauer'=>$dur,'materialien'=>$input['materialien']?:null,'hinweise'=>$input['hinweise']?:null,'quellen'=>$input['quellen']?:null,'tags'=>$input['tags'],'freigabe'=>$input['freigabe']]);$id=(int)$db->lastInsertId();}
$db->prepare('DELETE FROM coaching_format_freigaben WHERE format_id=:id')->execute(['id'=>$id]);
if($input['freigabe']==='ausgewaehlte_coaches'){$valid=$db->prepare("SELECT COUNT(*) FROM benutzer WHERE aktiv=1 AND rolle='coach' AND id=:coach");$insert=$db->prepare('INSERT INTO coaching_format_freigaben (format_id,coach_benutzer_id) VALUES (:format,:coach)');foreach($shareIds as $recipient){if($recipient===$coach)continue;$valid->execute(['coach'=>$recipient]);if((int)$valid->fetchColumn()!==1)throw new RuntimeException('Mindestens eine ausgewählte Person ist kein aktiver Coach.');$insert->execute(['format'=>$id,'coach'=>$recipient]);}}
$db->commit();header('Location: formats.php?saved=1');exit;}catch(Throwable $e){if($db->inTransaction())$db->rollBack();$error=$e instanceof RuntimeException?$e->getMessage():'Format konnte nicht gespeichert werden. Bitte Migration 006 und Tabellenrechte prüfen.';error_log('Coaching formats save failed: '.$e->getMessage());$values=array_merge($values,$input);$values['id']=$id;}}
}
$search=trim((string)($_GET['q']??''));$sql='SELECT DISTINCT f.*,b.vorname AS autor_vorname,b.nachname AS autor_nachname FROM coaching_formate f INNER JOIN benutzer b ON b.id=f.coach_benutzer_id WHERE (f.coach_benutzer_id=:owner OR f.freigabe=\'alle_coaches\' OR EXISTS (SELECT 1 FROM coaching_format_freigaben a WHERE a.format_id=f.id AND a.coach_benutzer_id=:viewer))';$params=['owner'=>$coach,'viewer'=>$coach];
if($search!==''){$sql.=' AND (f.titel LIKE :title_q OR f.kategorie LIKE :category_q OR f.kurzbeschreibung LIKE :desc_q OR f.tags LIKE :tags_q)';$like='%'.$search.'%';$params['title_q']=$like;$params['category_q']=$like;$params['desc_q']=$like;$params['tags_q']=$like;}
$sql.=' ORDER BY CASE WHEN f.coach_benutzer_id=:owner_order THEN 0 ELSE 1 END, f.kategorie,f.titel LIMIT 200';$params['owner_order']=$coach;$q=$db->prepare($sql);$q->execute($params);$entries=$q->fetchAll(PDO::FETCH_ASSOC);
?>
<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NLP-Formate</title><link rel="stylesheet" href="assets/layout.css"><style>.page{max-width:1200px;margin:auto;padding:34px clamp(24px,4vw,58px) 62px}.grid{display:grid;grid-template-columns:minmax(320px,440px) 1fr;gap:18px;align-items:start}.card,.article{background:white;border:1px solid #e4ebe6;border-radius:14px;padding:20px;margin:16px 0}.form{display:grid;gap:10px}.form input,.form select,.form textarea{width:100%;padding:10px;border:1px solid #dce5df;border-radius:8px;font:inherit}.form textarea{min-height:90px;resize:vertical}.button{background:#245c50;color:white;border:0;border-radius:8px;padding:11px 14px;font:inherit}.meta{color:#6d7b74;font-size:13px}.article{white-space:normal}.article-content{white-space:pre-wrap;line-height:1.6}.notice,.error{padding:12px;border-radius:8px}.notice{background:#edf5ef}.error{background:#fff3f1}.search{display:flex;gap:8px}.search input{flex:1;min-width:0;padding:10px;border:1px solid #dce5df;border-radius:8px}.coach-picks{max-height:170px;overflow:auto;border:1px solid #e4ebe6;padding:10px;border-radius:8px}.coach-picks label{display:block;padding:5px}@media(max-width:950px){.grid{grid-template-columns:1fr}}</style></head><body class="has-app-sidebar"><?php require_once dirname(__DIR__).'/app/navigation.php';renderCoachingSidebar($user,'formats',$token);?><main class="page"><h1>NLP-Formate</h1><p>Eine interne, durchsuchbare Wissenssammlung für Coaching-Formate. Teile nur fachliche Inhalte, keine identifizierenden Klientendaten.</p><?php if($notice):?><p class="notice"><?=formatH($notice)?></p><?php endif;?><?php if($error):?><p class="error"><?=formatH($error)?></p><?php endif;?>
<form class="search" method="get"><input name="q" value="<?=formatH($search)?>" placeholder="Formate, Kategorien oder Schlagwörter suchen"><button class="button">Suchen</button><a class="button" href="formats.php">Neues Format</a></form>
<div class="grid"><section class="card"><h2><?=!empty($values['id'])?'Eigenes Format bearbeiten':'Format anlegen'?></h2><form method="post" class="form"><input type="hidden" name="csrf_token" value="<?=formatH($token)?>"><input type="hidden" name="id" value="<?=(int)$values['id']?>"><label>Titel<input name="titel" maxlength="190" required value="<?=formatH($values['titel'])?>"></label><label>Kategorie<input name="kategorie" maxlength="100" value="<?=formatH($values['kategorie'])?>" placeholder="z. B. Zielarbeit, Ressourcen, Reframing"></label><label>Kurzbeschreibung<input name="kurzbeschreibung" maxlength="1000" value="<?=formatH($values['kurzbeschreibung'])?>"></label><label>Ziel / Einsatzbereich<textarea name="ziel"><?=formatH($values['ziel']??'')?></textarea></label><label>Ablauf in Schritten<textarea name="ablauf" required><?=formatH($values['ablauf'])?></textarea></label><label>Dauer in Minuten<input type="number" min="1" max="600" name="dauer_minuten" value="<?=formatH($values['dauer_minuten']??'')?>"></label><label>Materialien<textarea name="materialien"><?=formatH($values['materialien']??'')?></textarea></label><label>Hinweise / Grenzen<textarea name="hinweise"><?=formatH($values['hinweise']??'')?></textarea></label><label>Quellen / Literatur<textarea name="quellen"><?=formatH($values['quellen']??'')?></textarea></label><label>Schlagwörter<input name="tags" maxlength="500" value="<?=formatH($values['tags'])?>" placeholder="Komma-getrennt"></label><label>Freigabe<select name="freigabe"><?php foreach($visibility as $key=>$label):?><option value="<?=formatH($key)?>" <?=$values['freigabe']===$key?'selected':''?>><?=formatH($label)?></option><?php endforeach;?></select></label><div class="meta">Nur bei Freigabe „Ausgewählte Coaches“ wirksam. Diese Coaches können den Eintrag lesen, aber nicht ändern.</div><div class="coach-picks"><?php foreach($coaches as $person):if((int)$person['id']===$coach)continue;?><label><input type="checkbox" name="freigabe_an[]" value="<?=(int)$person['id']?>" <?=in_array((int)$person['id'],$selected,true)?'checked':''?>> <?=formatH($person['vorname'].' '.$person['nachname'])?></label><?php endforeach;?></div><button class="button">Format speichern</button><?php if(!empty($values['id'])):?><a href="formats.php">Abbrechen</a><?php endif;?></form></section>
<section><h2>Bibliothek (<?=count($entries)?>)</h2><?php if(!$entries):?><p>Noch keine passenden Formate vorhanden.</p><?php else:foreach($entries as $f):?><article class="article"><div class="meta"><?=formatH($f['kategorie']?:'Ohne Kategorie')?> · <?=formatH($f['autor_vorname'].' '.$f['autor_nachname'])?> · <?=((int)$f['coach_benutzer_id']===$coach?'Eigener Eintrag':($f['freigabe']==='alle_coaches'?'Mit allen Coaches geteilt':'Mit dir geteilt'))?></div><h2><?=formatH($f['titel'])?></h2><?php if($f['kurzbeschreibung']):?><p><?=formatH($f['kurzbeschreibung'])?></p><?php endif;?><p class="meta"><?=formatH($f['tags'])?></p><?php if($f['ziel']):?><h3>Ziel / Einsatzbereich</h3><div class="article-content"><?=formatH($f['ziel'])?></div><?php endif;?><h3>Ablauf</h3><div class="article-content"><?=formatH($f['ablauf'])?></div><?php if($f['dauer_minuten']):?><p><strong>Dauer:</strong> <?=formatH($f['dauer_minuten'])?> Min.</p><?php endif;?><?php if($f['materialien']):?><h3>Materialien</h3><div class="article-content"><?=formatH($f['materialien'])?></div><?php endif;?><?php if($f['hinweise']):?><h3>Hinweise / Grenzen</h3><div class="article-content"><?=formatH($f['hinweise'])?></div><?php endif;?><?php if($f['quellen']):?><h3>Quellen / Literatur</h3><div class="article-content"><?=formatH($f['quellen'])?></div><?php endif;?><?php if((int)$f['coach_benutzer_id']===$coach):?><p><a href="formats.php?edit=<?=(int)$f['id']?>">Eigenen Eintrag bearbeiten</a></p><?php endif;?></article><?php endforeach;endif;?></section></div></main></body></html>